import{readFile,writeFile}from'node:fs/promises';const root='docs/qa/layout-audit-2026-11-16';const data=JSON.parse(await readFile(root+'/round3/results.json','utf8'));const names={original:'初代牌桌',balanced:'均衡环形',oval:'竞技椭圆',classic:'经典'};const refs={original:'original-full-original.png',balanced:'balanced-100-original.png',oval:'oval-100-crop.png',classic:'classic-100-crop.png'};
let html='<!doctype html><meta charset="utf-8"><title>布局差异与昵称修正</title><style>body{font:15px/1.6 system-ui;margin:24px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ccc;padding:10px;vertical-align:top}img{width:100%;max-width:440px;height:auto}a{color:#1764a4}</style><h1>布局差异与昵称修正 · 最新验收</h1><p>初代遵循自身原稿；无间距公共牌与头像上方昵称规则仅适用于三种新布局。本人弃牌按钮倒计时保留用户此前确认的要求。本报告覆盖离线真实组件，不代表在线牌局验收。</p><p>初代恢复固定五牌位（局部中心 −281、−140、0、140、281；牌宽120），保留20/21局部单位间距。初代下注位置、普通操作气泡配色恢复原规则。新布局昵称底边锚定头像上缘，与筹码容器高度解耦，五档字号下分别检查昵称不碰头像和气泡。</p><p><a href="results.json">60项逐座位坐标与间距记录</a>；下方左右分别为 Figma 原图与当前实现，牌值与玩家状态为合成数据。</p>';
for(const[layout,name]of Object.entries(names)){html+=`<h2>${name}</h2><table><tr><th>Figma 原稿</th><th>当前 440×782 / 100%</th></tr><tr><td><a href="../reference/${refs[layout]}"><img src="../reference/${refs[layout]}"></a></td><td><a href="${layout}-440-100.png"><img src="${layout}-440-100.png"></a></td></tr></table><table><tr><th>尺寸</th><th>字号档位</th><th>验收</th><th>110% 截图</th></tr>`;for(const width of[320,375,440]){const rows=data.filter(r=>r.layout===layout&&r.width===width);html+=`<tr><td>${width}×${rows[0].height}</td><td>${rows.map(r=>r.scale+'%').join(' / ')}</td><td>${layout==='original'?'保留公共牌间距':'公共牌零间距；昵称与头像、气泡均无重叠'}：${rows.length} 项通过</td><td><a href="${layout}-${width}-110.png">查看截图</a></td></tr>`;}html+='</table>';}
await writeFile(root+'/round3/index.html',html);
for(const file of['index.html','round2/index.html']){let old=await readFile(root+'/'+file,'utf8');const href=file.startsWith('round2')?'../round3/index.html':'round3/index.html';const banner=`<p style="padding:20px;background:#ffe9a5"><a href="${href}">最新：初代布局区分及新布局昵称修正</a>。本页为上一轮记录；初代公共牌已恢复间距，以下旧截图与说明不代表最终规则。</p>`;old=old.includes('<body')?old.replace(/(<body[^>]*>)/,'$1'+banner):banner+old;await writeFile(root+'/'+file,old);}
console.log('Built latest report');
